function SourceForm({ busy, projectName, userName, onClose, onSave }: { busy: boolean; projectName: string; userName: string; onClose: () => void; onSave: (input: SourceInput) => Promise<void> }) {
  const [data, setData] = useState<SourceInput>({ title: '', kind: 'paper', authors: '', date: '', projectName, tags: [], content: '', locator: '', url: '' })
  function change(key: keyof SourceInput, value: string) { setData(current => ({ ...current, [key]: key === 'tags' ? value.split(/[，,]/).map(v => v.trim()).filter(Boolean) : value })) }
  return <Modal title="添加知识资料" onClose={onClose} wide><form onSubmit={e => { e.preventDefault(); void onSave(data) }}><div className="ks-form-grid"><label className="ks-field">资料类型<select value={data.kind} onChange={e => change('kind', e.target.value)}>{(['paper','practice','note'] as SourceKind[]).map(kind => <option key={kind} value={kind}>{kinds[kind]}</option>)}</select></label><label className="ks-field">资料标题<input required value={data.title} maxLength={300} onChange={e => change('title', e.target.value)} /></label><label className="ks-field">作者 / 记录人<input value={data.authors} placeholder={data.kind === 'paper' ? '未知可留空' : userName} onChange={e => change('authors', e.target.value)} /></label><label className="ks-field">发表 / 记录日期<input type="date" value={data.date} onChange={e => change('date', e.target.value)} /></label><label className="ks-field">关联项目<input value={data.projectName} onChange={e => change('projectName', e.target.value)} /></label><label className="ks-field">标签（逗号分隔）<input value={data.tags.join(',')} onChange={e => change('tags', e.target.value)} /></label><label className="ks-field">原文位置 / 实验编号<input value={data.locator} onChange={e => change('locator', e.target.value)} placeholder="章节、页码或实验编号；未知可留空" /></label><label className="ks-field">原文链接 / DOI URL<input type="url" value={data.url} onChange={e => change('url', e.target.value)} placeholder="https://" /></label></div><label className="ks-field">正文 / 原始记录<textarea required rows={9} value={data.content} onChange={e => change('content', e.target.value)} placeholder={data.kind === 'practice' ? '记录实验条件、观察结果、失败情况与适用限制…' : '粘贴有权使用的原文，保留段落和上下文…'} /></label><p className="ks-muted">未知元数据请留空。资料会进入当前账号有权维护的知识范围。</p><footer><Button onClick={onClose}>取消</Button><button className="ks-button ks-primary" disabled={busy || !data.title.trim() || !data.content.trim()}>{busy ? '保存中…' : '保存资料'}</button></footer></form></Modal>
}
function FormulaEditor({ rows, references, disabled, onChange }: { rows: FormulaRow[]; references: Reference[]; disabled: boolean; onChange: (rows: FormulaRow[]) => void }) {
  const [expanded, setExpanded] = useState<string | null>(null)
  function edit(id: string, patch: Partial<FormulaRow>) { onChange(rows.map(row => row.id === id ? { ...row, ...patch } : row)) }
  const sameBasis = rows.length > 0 && rows.every(row => row.unit && row.basis && row.unit === rows[0].unit && row.basis === rows[0].basis && /^\d+(\.\d+)?$/.test(row.amount))
  return <section className="ks-formula"><div className="ks-section-heading"><div><span className="ks-eyebrow">FORMULATION</span><h3>候选配方表</h3></div><Button disabled={disabled} onClick={() => { const id = uid(); onChange([...rows, { id, material: '', purpose: '', specification: '', amount: '', unit: '', basis: '', range: '', rationale: '', evidenceIds: [], verification: 'pending' }]); setExpanded(id) }}><Plus size={14} />添加物料</Button></div><div className="ks-table-scroll"><table><thead><tr><th>物料 / 用途</th><th>目标用量</th><th>单位</th><th>计量基准</th><th>验证状态</th><th aria-label="操作" /></tr></thead><tbody>{rows.map(row => <tr key={row.id}><td><input aria-label="物料名称" disabled={disabled} value={row.material} placeholder="物料名称" onChange={e => edit(row.id, { material: e.target.value })} /><input className="ks-small-input" aria-label={`${row.material}用途`} disabled={disabled} value={row.purpose} placeholder="类别或用途" onChange={e => edit(row.id, { purpose: e.target.value })} /></td><td><input aria-label={`${row.material}目标用量`} disabled={disabled} value={row.amount} placeholder="待验证" onChange={e => edit(row.id, { amount: e.target.value })} /></td><td><input aria-label={`${row.material}单位`} disabled={disabled} value={row.unit} placeholder="单位" onChange={e => edit(row.id, { unit: e.target.value })} /></td><td><input aria-label={`${row.material}计量基准`} disabled={disabled} value={row.basis} placeholder="每批 / 每单位" onChange={e => edit(row.id, { basis: e.target.value })} /></td><td><select aria-label={`${row.material}验证状态`} disabled={disabled} value={row.verification} onChange={e => edit(row.id, { verification: e.target.value as FormulaRow['verification'] })}><option value="pending">待验证</option><option value="confirmed">已确认</option></select></td><td><Button aria-label={`展开${row.material || '物料'}依据`} onClick={() => setExpanded(expanded === row.id ? null : row.id)}><ChevronDown size={15} /></Button></td></tr>)}</tbody></table></div>{!rows.length && <p className="ks-empty-small">尚未添加配方项。记录物料与计量基准，并保留选择依据。</p>}{rows.filter(row => row.id === expanded).map(row => <div key={row.id} className="ks-formula-detail"><div className="ks-form-grid">{([['specification','规格'], ['range','可选范围'], ['rationale','选择理由']] as const).map(([key, label]) => <label key={key} className="ks-field">{label}<input value={row[key]} disabled={disabled} onChange={e => edit(row.id, { [key]: e.target.value })} /></label>)}<label className="ks-field">关联依据<select multiple value={row.evidenceIds} disabled={disabled} onChange={e => edit(row.id, { evidenceIds: Array.from(e.target.selectedOptions, option => option.value) })}>{references.map(reference => <option key={reference.id} value={reference.id}>{reference.title} · {reference.sourceVersion}</option>)}</select></label></div><Button disabled={disabled} onClick={() => { onChange(rows.filter(item => item.id !== row.id)); setExpanded(null) }}><Trash2 size={14} />删除此物料</Button></div>)}<div className="ks-table-note">{sameBasis ? `同一基准合计：${Number(rows.reduce((total, row) => total + Number(row.amount), 0).toFixed(6))} ${rows[0].unit} · ${rows[0].basis}` : '仅同单位、同计量基准且用量为数值时合计；待定数值不参与换算。'}</div></section>
}
function ReviewDialog({ action, reviewers, userId, userName, busy, onClose, onConfirm }: { action: ReviewAction['action']; reviewers: Reviewer[]; userId: string; userName: string; busy: boolean; onClose: () => void; onConfirm: (note: string, reviewerId: string) => Promise<void> }) {
  const [note, setNote] = useState(''), [reviewer, setReviewer] = useState(userId)
  const titles: Record<ReviewAction['action'], string> = { submit: '提交报告评审', withdraw: '撤回评审', approve: '确认通过并定稿', return: '退回修改', revise: '建立下一版草稿', archive: '归档报告', restore: '恢复历史版本' }
  const allReviewers = reviewers.some(r => r.id === userId) ? reviewers : [{ id: userId, name: userName }, ...reviewers]
  return <Modal title={titles[action]} onClose={onClose}><form onSubmit={e => { e.preventDefault(); void onConfirm(note, reviewer) }}>{action === 'submit' && <label className="ks-field">指定评审者<select value={reviewer} onChange={e => setReviewer(e.target.value)}>{allReviewers.map(r => <option value={r.id} key={r.id}>{r.name}{r.id === userId ? '（作者确认）' : ''}</option>)}</select></label>}<p className="ks-muted">{action === 'submit' ? '提交后形成评审快照，正文暂时锁定。需要编辑时可撤回。' : action === 'approve' ? '定稿将保留当前正文、配方、引用和评审结论。' : action === 'revise' || action === 'restore' ? '将创建新的草稿版本，既有历史记录继续保留。' : '本次操作及理由将保留在版本记录中。'}</p><label className="ks-field">{action === 'approve' ? '评审结论与待验证事项' : '说明 / 理由'}<textarea autoFocus rows={5} required value={note} onChange={e => setNote(e.target.value)} placeholder="请记录判断依据和后续安排…" /></label><footer><Button onClick={onClose}>取消</Button><button className="ks-button ks-primary" disabled={busy || !note.trim()}>{busy ? '处理中…' : titles[action]}</button></footer></form></Modal>
}

