  function stageSource(source: KnowledgeSource) { if (!currentSection) return; setInsert({ content: source.content.slice(0, 4000), sectionId: currentSection.id, type: '原文引用', refs: [{ id: uid(), sourceId: source.id, title: source.title, excerpt: source.content.slice(0, 1200), locator: source.locator, sourceVersion: source.version, sectionId: currentSection.id }] }); setSourceOpen(null) }
  function confirmInsert() { if (!insert || !doc) return; const target = doc.sections.find(s => s.id === insert.sectionId); if (!target) return; const refs = insert.refs.map(ref => ({ ...ref, id: uid(), sectionId: target.id })); const citation = refs.map(ref => `[依据：${ref.title} · ${ref.sourceVersion} · ${ref.locator || '正文片段'}]`).join('\n'); const added = `\n\n${insert.type === '待验证项' ? '【待验证假设】\n' : insert.type === 'AI 辅助建议' ? '【AI 辅助建议 · 专家待核对】\n' : ''}${insert.content}${citation ? `\n\n${citation}` : ''}`; editDoc({ sections: doc.sections.map(s => s.id === target.id ? { ...s, content: s.content + added } : s), references: [...doc.references, ...refs] }); setSectionId(target.id); setUndo({ sectionId: target.id, added, referenceIds: refs.map(r => r.id) }); setInsert(null); setNotice('已插入当前章节并保留来源，请补充适用条件与专家判断。') }
