        <div className="ks-layout-toolbar"><Button className="ks-layout-open" aria-label="排列布局" onClick={() => setLayoutOpen(true)}><LayoutDashboard size={16} />排列布局<ChevronDown size={12} /></Button><span className="ks-layout-name">{arrangementLabels[workspaceLayout.arrangement]}</span><div className="ks-module-legend">{workspaceLayout.order.map((module, index) => panels.visible[module] ? <span key={module}><b>{index + 1}</b>{moduleLabels[module]}</span> : <Button key={module} aria-label={`展开${moduleLabels[module]}`} onClick={() => toggleModule(module)}><b>{index + 1}</b>{moduleLabels[module]} · 展开</Button>)}</div></div>
